// Compute Purge Cutoff (CP5e) — delete processed_messages older than 30 days (dedupe only needs to
// survive the provider retry window = hours; 30d is amply safe). created_at is an ISO-8601 UTC string,
// so a lexicographic '<' compare is chronological.
return [{ json: { cutoff: $now.minus({ days: 30 }).toUTC().toISO() } }];

// Compute PII Cutoff (FIX-1) — conversations.recent_messages is PII (the rolling last-5 customer
// message texts). It is SCRUBBED after 30 days; the ROW is deliberately KEPT.
// WHY not delete the row: deleting it would silently release a stage='handoff' lock (a handed-off
// customer would start getting bot replies again with no human action) and would drop
// cancel_target_id / confirm_turn state. Row deletion is a SEPARATE decision — UX-ARCHITECTURE §9 K2.
// HONEST SCOPE: this scrubs message CONTENT only. sender_key (a phone number on whatsapp) stays for
// the row's lifetime — this is not a full PII expiry.
return [{ json: { pii_cutoff: $now.minus({ days: 30 }).toUTC().toISO() } }];

// Load Config (Purge) — FIX-1. The purge workflow can now ALERT, so it needs the shared ownerAlert
// config. Mirrors the reminders pattern (each workflow carries its own inline config).
// SHARED KEY CONTRACT: ownerAlert.{enabled,throttleMinutes} MUST equal the main + reminders Load Configs
// — asserted by scripts/check-cancel-validation-parity.py. A kill that silences only some alerts is not a kill.
// one-swap-to-real: replace this literal with client.config.json / an n8n variable (Phase 4/template).
const config = {
  ownerAlert: { enabled: true, throttleMinutes: 30 },
  // leads TTL (CP 6d-1). ABSENT would make the leads branch refuse and alert — fail-closed by
  // design, because a retention default nobody chose is how a wrong cutoff sweeps a table.
  leadsRetentionDays: 90
};
return [{ json: { ...$json, config } }];

// Purge Error (processed) — error collector. Tags WHICH cleanup failed; n8n's error item does not carry the
// failing node name, so the branch is identified by topology (this node's own identity).
return $input.all().map(i => ({ json: { ...i.json, _purge_branch: 'processed_messages' } }));

// Purge Error (PII) — error collector. Tags WHICH cleanup failed; n8n's error item does not carry the
// failing node name, so the branch is identified by topology (this node's own identity).
return $input.all().map(i => ({ json: { ...i.json, _purge_branch: 'conversations_pii' } }));

// Owner-alert (Purge) — FIX-1. A purge failure used to be INVISIBLE: this workflow had no alert at all,
// so if the dedupe purge or the PII scrub stopped, the data just quietly stopped being cleaned.
// Same silent-failure class as cancel_mirror_failed (A1).
//
// WHY THE THROTTLE KEY CARRIES THE BRANCH (drill-corrected, exec 1631): n8n runs a node ONCE PER INCOMING
// CONNECTION, not once with the inputs merged — so $input.all() only ever sees ONE collector. The first
// build attempt threw both collectors at a single global 'purge_error' throttle key: run#0 (processed)
// alerted, run#1 (PII) hit the key it had just set and returned [] — the PII failure was SWALLOWED, the
// exact thing the two collectors exist to prevent. Keying on class+branch makes the two branches
// independent: each gets its own alert, and each still gets its own storm brake.
const lc = $('Load Config (Purge)').first().json;
const cfg = (lc && lc.config) ? lc.config : {};
const oa = cfg.ownerAlert || {};
if (oa.enabled !== true) return [];
const items = $input.all();
const branch = (items[0] && items[0].json && items[0].json._purge_branch) || 'unknown';
let detail = 'unknown';
try { const e = items[0].json || {}; detail = (e.error && e.error.message) || e.message || e.error || 'unknown'; } catch (x) {}
const cls = 'purge_error';
const windowMin = Number(oa.throttleMinutes) > 0 ? Number(oa.throttleMinutes) : 30;
const key = cls + ':' + branch;
const now = Date.now();
const sd = $getWorkflowStaticData('global');
sd.ownerAlerts = sd.ownerAlerts || {};
if (typeof sd.ownerAlerts[key] === 'number' && (now - sd.ownerAlerts[key]) < windowMin*60*1000) return [];
sd.ownerAlerts[key] = now;
const text = ('\ud83d\udd14 Salon bot \u2014 purge-error\nbranch: ' + branch +
              '\nfailed items: ' + items.length + '\ndetail: ' + String(detail)).replace(/[_*`\[\]~]/g,'-');
return [{ json: { owner_alert_text: text, _alert_class: cls, _purge_branch: branch } }];

// Owner-alert delivery failed (Telegram). Visible marker; the purge run itself is unaffected.
// Terminal on purpose — alerting about a failed alert would recurse.
return [{ json: { owner_alert_failed: true } }];

// B1 · Compute Leads Cutoff — the public demo's lead capture takes REAL phone numbers from strangers
// (ARCH-DEC D-11) and `leads` had no TTL at all. This is the third fan-out from Load Config (Purge).
//
// FAIL-CLOSED ON PURPOSE: when `leadsRetentionDays` is absent the branch deletes NOTHING and routes to the
// alert. A retention policy that quietly defaults to a number nobody chose is exactly how one arithmetic
// slip becomes a swept table — and Airtable has no undo.
const lc = $('Load Config (Purge)').first().json;
const days = ((lc && lc.config) || {}).leadsRetentionDays;
if (!Number.isInteger(days) || days < 1) {
  return [{ json: { _purge_branch: 'leads', _leads_refused: 'no_retention_configured' } }];
}
return [{ json: { cutoff: $now.minus({ days }).toUTC().toISO(), retention_days: days } }];

// Collapse the row-per-item output of Count Leads Total into ONE item carrying only the count.
// WHY THIS NODE EXISTS: an n8n Airtable search runs ONCE PER INCOMING ITEM. Feeding 44 rows into
// Find Old Leads made it run 44 times and report 264 candidates against a 44-row table — the cap
// refused the run, which is the only reason that was a finding rather than an incident (drill, exec 2764).
return [{ json: { leads_total: $input.all().filter(i => i.json && i.json.id).length } }];

// B3 · THE CANDIDATE CAP — the single most important node in this branch.
// A mis-computed cutoff is one arithmetic slip. WITHOUT a cap its cost is the whole table; WITH one its
// cost is a Telegram message. Cap = min(200, 20% of the table).
//
// ⚠ MEASURED GAP, recorded rather than silently accepted: rows whose `created_at` is EMPTY never match
// `{created_at} < cutoff`, so they are never candidates and never expire. 3 of 41 rows were in that state
// when this was built. The cap does not fix it and must not be read as if it did.
const CAP_ABS = 200, CAP_PCT = 0.20;
const cut = $('Compute Leads Cutoff').first().json;
const total = $('Aggregate Leads Total').first().json.leads_total;
const rows = $input.all().filter(i => i.json && i.json.id);
const cap = Math.min(CAP_ABS, Math.floor(total * CAP_PCT));
const within = rows.length > 0 && rows.length <= cap;

if (!within) {
  return [{ json: { _purge_branch: 'leads',
    _leads_refused: rows.length === 0 ? 'no_candidates' : 'leads_purge_capped',
    candidates: rows.length, cap, total, cutoff: cut.cutoff } }];
}
// Carry the rows through, each tagged, so the delete node receives one item per record to delete.
return rows.map(i => ({ json: { id: i.json.id, _within_cap: true,
  _candidates: rows.length, _cap: cap, _total: total, _cutoff: cut.cutoff } }));

// B7 · Verify Leads Purge — ARITHMETIC PROOF, because "the delete returned 200" is not "the rows are gone".
// before − after === deleted, or the branch alerts. A delete that reports success and removes nothing, and
// one that removes more than it was asked to, both fail this check and both are silent without it.
const sane = $('Leads Purge Sane?').first().json;
const before = sane._candidates;
const deleted = $('Delete Old Leads').all().filter(i => i.json && !i.json.error).length;
const after = $('Count Leads After').all().filter(i => i.json && i.json.id).length;

if (before - after !== deleted) {
  return [{ json: { _purge_branch: 'leads', _leads_refused: 'leads_purge_arithmetic_mismatch',
                    before, after, deleted } }];
}
return [];   // clean run: nothing to alert about

// Error + refusal collector for the leads branch. n8n's error item does not carry the failing node name,
// so the branch is identified by this node's own identity — the same topology trick the other two
// collectors use. Keyed per branch so the two existing branches cannot swallow this one's alert
// (drill-corrected once already, exec 1631).
return $input.all().map(i => ({ json: { ...i.json, _purge_branch: 'leads' } }));
